#include "stdafx.h"#include <macros/AutoCloser.h>#include "ServerThreadBase.h"#include "LogFile.h"SExtensions g_extensionsCont[ecCount] = { NULL };static LPCSTR s_szMasks[] = { "ServerExPlugin_*", "ServerExSharedPlugin_*" };void LoadPlugins(){	CLogFile::Initialize ("ServerExBase", TRUE, FALSE, "ServerBase.txt");  LPCSTR pExe = GetExePath();  char szMask[_MAX_PATH] = { 0 };  WIN32_FIND_DATA find;  int c = 0;  for( int i=0; i<_countof(s_szMasks); ++i )  {    _makepath_s( szMask, NULL, pExe, s_szMasks[i], "dll");    BOOL bResult = TRUE;    KAutoCloser<HANDLE> hFind( FindFirstFile( szMask, &find ),                                FindClose );    if( INVALID_HANDLE_VALUE==hFind )      continue;    while( bResult )    {      _makepath_s( szMask, NULL, pExe, find.cFileName, NULL);      HMODULE hm = LoadLibrary( szMask );	  CLogFile::Log ("LoadPlugins started: szMask %s", szMask);      if( hm )      {        g_extensionsCont[c].pExtractumRSUCall = (tExtractumRSU)GetProcAddress( hm, "ExtractumRSU" );        g_extensionsCont[c].pSizeShRSUCall = (tSizeShRSU)GetProcAddress( hm, "SizeShRSU" );        g_extensionsCont[c].pPutModelRSUCall = (tPutModelRSU)GetProcAddress( hm, "PutModelRSU" );        g_extensionsCont[c].pGetRsuData = (tGetRsuData)GetProcAddress( hm, "GetRsuData" );        g_extensionsCont[c].pAlarmsSupport = (tAlarmsSupport)GetProcAddress( hm, "AlarmsSupport" );        g_extensionsCont[c].pMessagesSupport = (tAlarmsSupport)GetProcAddress( hm, "MessagesSupport" );        g_extensionsCont[c].pAnyOtherRequest = (tAnyGetSetRequest)GetProcAddress( hm, "AnyOtherRequest" );        g_extensionsCont[c].pEventsSupport = (tAlarmsSupport)GetProcAddress( hm, "EventsSupport" );        g_extensionsCont[c].pFindConnPointEx = (tFindConnPointEx)GetProcAddress( hm, "FindConnPointEx" );        g_extensionsCont[c].pFindHoney = (tFindHoney)GetProcAddress( hm, "FindHoney" );        strncpy_s( g_extensionsCont[c].szLibraryName, find.cFileName, _countof(g_extensionsCont[c].szLibraryName)-1 );		CLogFile::Log ("LoadPlugins: c %d, szLibraryName %s", c, g_extensionsCont[c].szLibraryName);        c++;        if( c==_countof(g_extensionsCont) )          break;      }      bResult = FindNextFile( hFind, &find );    }  }  CLogFile::Log ("LoadPlugins finished: c %d", c);}